import math

def check_expression(n):
    # N = 3((n+2)! + 1)
    # D = 2n - 1

    if 2 * n - 1 <= 0:
        return f"n={n}: Denominator is non-positive (2n-1={2*n - 1}), undefined/problematic."

    try:
        factorial_val = math.factorial(n + 2)
        numerator = 3 * (factorial_val + 1)
        denominator = 2 * n - 1

        if numerator % denominator == 0:
            result = numerator // denominator
            return f"n={n}: Integer. Value = {result}"
        else:
            return f"n={n}: Not an integer. Numerator % Denominator = {numerator % denominator}"

    except OverflowError:
        # This should theoretically not happen for n up to 8, but good practice.
        return f"n={n}: Overflow encountered during factorial calculation."

# Test cases
n_values = [5, 6, 7, 8]
for n in n_values:
    print(check_expression(n))

