def check_divisibility(p):
    # p = 2n - 1. n = (p+1)/2. n+2 = (p+5)/2.
    n_plus_2 = (p + 5) // 2

    # We check p | 3((n+2)! + 1)
    numerator = 3 * (math.factorial(n_plus_2) + 1)

    if numerator % p == 0:
        return True
    else:
