def is_prime(m):
    if m < 2: return False
    for i in range(2, int(m**0.5) + 1):
        if m % i == 0:
            return False
    return True

def check_n(n):
    m = 2 * n - 1
    if m == -1: return True
    if m == 1: return True
    if m == 3: return True
    if not is_prime(m): return False

    # Condition: (-1)^{n-4} (n-4)! \equiv 1 \pmod m
    # or (n+2)! \equiv -1 \pmod m
    # We can use Wilson's Theorem: (m-1)! \equiv -1 \pmod m
    # (m-1)! = (2n-2)! \equiv -1 \pmod{2n-1}
    # (n+2)! \equiv -1 \pmod{2n-1}
    # (n+2)! \equiv (2n-2)! \pmod{2n-1}
    # (n+3)(n+4)...(2n-2) \equiv 1 \pmod{2n-1}
    # This is (-1)^{n-4} (n-4)! \equiv 1 \pmod{2n-1}

    if n == 4: return True

    # For n > 4, compute (n-4)! \pmod m
    fact = 1
    for i in range(1, n - 3):
        fact = (fact * i) % m

    if (n - 4) % 2 == 0:
        return fact == 1
    else:
        return fact == m - 1

results = []
for n in range(100000):
    if check_n(n):
        results.append(n)
print(results)

