        k = 2*n - 1
        if k == 0: continue

        # Check if 3 * ((n+2)! + 1) is divisible by k
        # This is equivalent to 3 * ((n+2)! + 1) % k == 0

        # Let's just calculate it for small n
        if n < 100:
